update public.fields set verification_status='verified_against_standard', verification_quote='In Tabelle A. 1 findet sich ein Beispiel für die Erstellung einer Risikoanalyse, das in Projekten der Wasserwirtschaft häufig auftretende Risikogruppen enthält. Die Risikoanalyse muss in der Praxis um eine Spalte „Präventions- und Korrekturmaßnahmen“ ergänzt werden, in der die projektspezifischen Maßnahmenpläne festgehalten werden (siehe Tabelle A.2). | Tabelle A.1: Beispiel einer Projekt-Risikoanalyse | Eintretenswahrscheinlichkeit 0: Risikofall tritt nicht ein (kein Eintritt) 5: Risiko kann eintreten (kann eintreten) 10: Hohe Wahrscheinlichkeit (tritt ein) | Schaden 0: Keine Auswirkungen 5: Mittlere Auswirkungen, Betriebsstörung 10: Große Auswirkungen, Katastrophe | Risiko 0: Kein Risiko 25: Mittleres Risiko 100: Sehr großes Risiko | Bauherr & Planer & Betrieb & M-Wert & S-Abw. — printed p.43, p.44', verification_note='md-verified 2026-09-05 (Anh. A p.43, Tab. A.1 p.44–45 (11 printed Risikogruppen, 0/5/10 anchors, M-Wert/S-Abw. columns); the table is a "Beispiel" and §4.7 p.22 says "Risiken sollten … systematisch erfasst werden" → is_required review in STAGED S-4) [VC]', verified_at=now() where id='777faf36-5289-4f8e-8df9-bc3f93acb193' and verification_status not in ('verified_against_standard','corrected');

-- risk_analysis_method
update public.fields set verification_status='verified_against_standard', verification_quote='Risiken sollten im Rahmen der Planung systematisch erfasst werden und sind hinsichtlich ihrer Auswirkungen auf das Konzept oder die Projekte zu bewerten. [...] Hierfür können einschlägige Methoden der Risikoanalyse verwendet werden. Ein Beispiel für eine Risikoanalyse eines großen Projekts ist in Anhang A dargestellt. Die Risikoanalyse ist über alle Projektphasen fortzuschreiben. — printed p.22', verification_note='md-verified 2026-09-05 (§4.7 p.22; enum qualitative_matrix (= Anh. A example) / other (= "einschlägige Methoden") 1:1) [VC]', verified_at=now() where id='1c43817c-2082-4878-b085-f78d8b0a651e' and verification_status not in ('verified_against_standard','corrected');

-- ---------- M820-07 Risiko-Maßnahmenplan ----------

-- risk_mitigation_plan
update public.fields set verification_status='verified_against_standard', verification_quote='Die Maßnahmenpläne sind für alle wichtigen und relevanten Risiken vorausschauend zu definieren, inklusive der Konsequenzen und der erforderlichen Kompetenzregelungen im Fall des Eintretens einer Projektstörung. | Zumindest sollten für diejenigen Risiken, welche einen hohen Schaden und eine hohe Eintrittswahrscheinlichkeit aufweisen, Maßnahmenpläne entwickelt werden. | Tabelle A.2: Beispiel für den Aufbau eines Risiko-Maßnahmenplans | Risiko | Wert | Risikokategorie/ -bereich | Schäden | Gefährdungsbilder | Maßnahmen: (Technische = T / Organisatorische = O / Personelle = P) | Verantwortung | Durchführen | Überwachung — printed p.43, p.46', verification_note='md-verified 2026-09-05 (Anh. A p.43 + p.46, Tab. A.2 p.46; "sollten … Maßnahmenpläne entwickelt werden" → is_required review in STAGED S-4) [VC]', verified_at=now() where id='38ae4950-9d09-48c8-a520-06ed81f89e50' and verification_status not in ('verified_against_standard','corrected');

-- ---------- M820-08 Rechtsrahmen ----------

-- hoai_applicable
update public.fields set verification_status='verified_against_standard', verification_quote='Die HOAI ist gesetzliches Preisrecht und regelt die Honorare für Leistungen von Architekten und Ingenieuren. Erfasst sind die meisten Ingenieurleistungen, die in der Wasserwirtschaft zu vergeben sind, soweit es um die Umsetzung von Projekten geht. Bei Bedarfsplanungen bzw. konzeptionellen Planungen (z. B. GEP) greift die HOAI in der Regel nicht. | Als Ingenieurleistungen gelten danach solche Leistungen, die von der Honorarordnung für Architekten und Ingenieure (HOAI) erfasst werden oder für die die berufliche Qualifikation des Ingenieurs vom Auftraggeber gefordert wird. — printed p.30, p.51', verification_note='md-verified 2026-09-05 (§7.4 p.30, Anh. B.2.4 p.51 (§73 VgV)) [VC]', verified_at=now() where id='290abd31-dcad-474a-9c58-8035800691ec' and verification_status not in ('verified_against_standard','corrected');

-- authority_oversight_required
update public.fields set verification_status='verified_against_standard', verification_quote='Die meisten Planungen müssen öffentlich-rechtlich genehmigt werden, weil u. a. Wasserrecht, Baurecht, Naturschutz- oder Denkmalschutzrecht berührt werden. [...] Behörden sind grundsätzlich frühzeitig zu beteiligen. — printed p.24', verification_note='md-verified 2026-09-05 (§5.5 p.24) [VC]', verified_at=now() where id='e55f5c69-641e-484a-8d4a-4be99e5b4951' and verification_status not in ('verified_against_standard','corrected');

-- applicable_legal_bases
update public.fields set verification_status='verified_against_standard', verification_quote='Ist der EU-Schwellenwert erreicht oder überschritten, so gelten für die in diesem Merkblatt behandelten Ingenieurleistungen folgende Vorschriften (siehe auch Bild B.1): | Auf europäischer Ebene: | Vertrag über die Arbeitsweise der Europäischen Union (AEUV, Primärrecht, wurde umgesetzt im GWB), | Vergaberichtlinie (VRL, Sekundärrecht, wurde umgesetzt in GWB und VgV). | Auf nationaler Ebene: | Gesetz gegen Wettbewerbsbeschränkungen (GWB), | Vergabeverordnung (VgV). | Auf nationaler Ebene: | Haushaltsrecht des Bundes (BHO) oder der Länder (LHO) und kommunale Regelungen, wie Gemeindehaushaltsordnungen (GemHO), | landesgesetzliche Regelungen für die öffentliche Auftragsvergabe (in den Bundesländern unterschiedlich). — printed p.47, p.48', verification_note='md-verified 2026-09-05 (Anh. B.1.2 p.47, B.1.3 p.48 (HOAI §7.4 p.30, BGB §7.3 p.30, UVgO/VOL/A §4.1 p.17); caveat: description token "GemO" — the source prints "GemHO" (Gemeindehaushaltsordnungen)) [VC]', verified_at=now() where id='5641ed98-de44-4b4b-b352-4e1f083295ed' and verification_status not in ('verified_against_standard','corrected');

