update public.fields set verification_status='verified_against_standard', verification_quote='Die EU-Schwellenwerte betragen laut Verordnung (EU) 2019/1828 vom 30.10.2019 ab dem 01.01.2020 für Planungsleistungen von Auftraggebern: | der obersten oder oberen Bundesbehörden oder vergleichbarer Institutionen 139.000 €, | für alle anderen 214.000 €. | Die EU-Schwellenwerte werden von der EU-Kommission alle zwei Jahre geprüft und durch Verordnung festgelegt. — printed p.49, p.47', verification_note='md-verified 2026-09-05 (Anh. B.2.3 p.49 (VO (EU) 2019/1828), B.1.1 p.47; printed values 139.000 € / 214.000 € are standard_fixed for the März-2020 edition but revised biennially — the field is deliberately engineer-editable (see Findings)) [VC]', verified_at=now() where id='5d988994-ea1a-49bb-82c8-ff4c2a67a1e9' and verification_status not in ('verified_against_standard','corrected');

-- threshold_status
update public.fields set verification_status='verified_against_standard', verification_quote='Erreicht oder übersteigt der geschätzte Netto-Gesamtwert den EU-Schwellenwert ist ein VgV-F-Verfahren durchzuführen. Liegt er darunter, hat der Auftraggeber ein Suchverfahren durchzuführen oder er kann in zugelassenen Ausnahmefällen eine Direktvergabe (siehe 8.8) vornehmen. | Ein Vergabeverfahren ist dem Oberschwellenbereich zuzuordnen, wenn der Nettogesamtwert der Planungsleitung den jeweils von der Europäischen Union durch Verordnung festgelegten Schwellenwert erreicht oder überschreitet. — printed p.34, p.12', verification_note='md-verified 2026-09-05 (§8.6 p.34, §3.1 p.12 (md prints "Planungsleitung"); enum oberschwellig/unterschwellig = §3.1 definitions 1:1) [VC]', verified_at=now() where id='ec4466c8-99b0-47d5-98b1-8fa527ec4fcb' and verification_status not in ('verified_against_standard','corrected');

-- loseausnahme_applicable
update public.fields set verification_status='verified_against_standard', verification_quote='Die Aufteilung in Lose regelt § 3 Abs. 9 VgV: „Der [...] Auftraggeber kann bei der Vergabe einzelner Lose von Absatz 7 Satz 3 sowie Absatz 8 abweichen, wenn der geschätzte Nettowert des betreffenden Loses bei Liefer- und Dienstleistungen unter 80000 Euro und bei Bauleistungen unter 1 Million Euro liegt und die Summe der Nettowerte dieser Lose 20 Prozent des Gesamtwertes aller Lose nicht übersteigt.“ | Soweit also die Teilaufträge insgesamt 20 % des Gesamtauftragswerts und je Teileauftrag 80.000 € nicht überschreiten, können diese nach nationalem Recht vergeben werden. — printed p.51', verification_note='md-verified 2026-09-05 (Anh. B.2.4 p.51 (§3 Abs. 9 VgV quoted verbatim by the source; md prints "Abs .9")) [VC]', verified_at=now() where id='602b2130-38ba-4e6d-bf03-29b5f8a29bec' and verification_status not in ('verified_against_standard','corrected');

