update public.fields set verification_status='verified_against_standard', verification_quote='Die Aufteilung in Lose regelt § 3 Abs. 9 VgV: „Der [...] Auftraggeber kann bei der Vergabe einzelner Lose von Absatz 7 Satz 3 sowie Absatz 8 abweichen, wenn der geschätzte Nettowert des betreffenden Loses bei Liefer- und Dienstleistungen unter 80000 Euro und bei Bauleistungen unter 1 Million Euro liegt und die Summe der Nettowerte dieser Lose 20 Prozent des Gesamtwertes aller Lose nicht übersteigt.“ | Soweit also die Teilaufträge insgesamt 20 % des Gesamtauftragswerts und je Teileauftrag 80.000 € nicht überschreiten, können diese nach nationalem Recht vergeben werden. — printed p.51', verification_note='md-verified 2026-09-05 (Anh. B.2.4 p.51 — printed constant 1 Mio. € net per lot (Bauleistungen); standard_fixed but hand-enterable (see Findings)) [VC]', verified_at=now() where id='52c7dd9c-cc7a-4083-b20a-b81fa4def8cf' and verification_status not in ('verified_against_standard','corrected');

