-- cost_estimate_near_threshold
update public.fields set verification_status='verified_against_standard', verification_quote='Die Ungenauigkeit bei den Kostenaufstellungen im Rahmen der Vorplanung kann aufgrund der vorgegebenen geringeren Detailtiefe bei ±25 % oder im Einzelfall noch höher liegen. Dies ist bei Entscheidungen zu berücksichtigen. | Der Auftraggeber hat also zunächst zu prüfen, ob der EU-Schwellenwert erreicht oder überschritten ist. Liegt der voraussichtliche Netto-Gesamtwert unterhalb der EU-Schwellenwerte, wird nachfolgend von einer nationalen Vergabe gesprochen. — printed p.19, p.48', verification_note='md-verified 2026-09-05 (§4.2 p.19, Anh. B.1.1 p.48; caveat: the source states the ±25 % uncertainty and the duty to check the threshold — the near-threshold flag itself is an EKOWAI derived construct (hand-enterable derived, see Findings)) [VC]', verified_at=now() where id='3f9e1f7c-f692-4235-8cd0-30b350452017' and verification_status not in ('verified_against_standard','corrected');

-- oberschwellig_check
update public.fields set verification_status='verified_against_standard', verification_quote='Der Auftraggeber hat also zunächst zu prüfen, ob der EU-Schwellenwert erreicht oder überschritten ist. Liegt der voraussichtliche Netto-Gesamtwert unterhalb der EU-Schwellenwerte, wird nachfolgend von einer nationalen Vergabe gesprochen. | In § 106 GWB ist festgelegt, dass das GWB und in Folge die VgV nur gelten, soweit der geschätzte Auftragswert die EU-Schwellenwerte erreicht oder überschreitet. — printed p.48, p.49', verification_note='md-verified 2026-09-05 (Anh. B.1.1 p.48, B.2.3 p.49; duplicate of threshold_status (STAGED S-2)) [VC]', verified_at=now() where id='38bb9560-2771-4eec-9019-cf8aa7d104ed' and verification_status not in ('verified_against_standard','corrected');

-- auftragswert_manipulation_check
update public.fields set verification_status='verified_against_standard', verification_quote='In § 3 VgV ist die Schätzung des Auftragswerts geregelt. Nach § 3 Abs. 1 VgV ist der voraussichtliche Gesamtwert der vorgesehenen Leistung zu ermitteln, wobei Optionen und Vertragsverlängerungen zu berücksichtigen sind. § 3 Abs. 2 VgV verbietet eine Schätzung oder Aufteilung in der Absicht, dadurch das europaweite Verfahren zu umgehen. — printed p.51', verification_note='md-verified 2026-09-05 (Anh. B.2.4 p.51) [VC]', verified_at=now() where id='f30a7524-8527-4a16-89bd-72d82367bd9a' and verification_status not in ('verified_against_standard','corrected');

-- ---------- M820-10 Verfahrenswahl ----------

-- procurement_procedure
update public.fields set verification_status='verified_against_standard', verification_quote='Erreicht oder übersteigt der geschätzte Netto-Gesamtwert den EU-Schwellenwert ist ein VgV-F-Verfahren durchzuführen. Liegt er darunter, hat der Auftraggeber ein Suchverfahren durchzuführen oder er kann in zugelassenen Ausnahmefällen eine Direktvergabe (siehe 8.8) vornehmen. | Es gibt weiterhin Schwellenwerte, ab denen europaweit ausgeschrieben werden muss (VgV-F-Verfahren, siehe 8.10). Im unterschwelligen Bereich kann national ausgeschrieben werden (Suchverfahren, siehe 8.9) bzw. eine Direktvergabe (siehe 8.8) erfolgen. | Wegen der Komplexität und Anforderungen an wasserwirtschaftliche Maßnahmen können vergütete Planungswettbewerbe zur Auswahl eines Ingenieurbüros im Ausnahmefall im Rahmen der Bedarfsplanung sinnvoll sein. — printed p.34, p.29, p.42', verification_note='md-verified 2026-09-05 (§8.6 p.34, §7.1 p.29, §8.11 p.42; enum = the four printed procedures 1:1) [VC]', verified_at=now() where id='1b45411a-7a63-47de-a51f-7d415adadbc4' and verification_status not in ('verified_against_standard','corrected');

-- procedure_rationale
update public.fields set verification_status='verified_against_standard', verification_quote='Die Gründe für eine Direktvergabe sind in jedem Fall zu dokumentieren, entweder im Vergabevermerk oder an anderer Stelle. | 1.6. Auswahl des Vergabeverfahrens | Hier muss die Auswahl des Vergabeverfahrens begründet werden. Als Grund genügt in der Regel der Verweis auf die Schätzung des Werts des zu vergebenden Auftrags und die damit einhergehende Darstellung, ob europaweit (VgV-F-Verfahren) oder national (Suchverfahren) vergeben wird. — printed p.36, p.65', verification_note='md-verified 2026-09-05 (§8.8 p.36, Anh. F 1.6 p.65) [VC]', verified_at=now() where id='8a70f3b5-450b-4df3-9155-1c019f83ea17' and verification_status not in ('verified_against_standard','corrected');

-- ---------- M820-11 Qualitätsanforderungen ----------

-- leistungswettbewerb_only
update public.fields set verification_status='verified_against_standard', verification_quote='Die Berücksichtigung der Qualität bei der Vergabe von Ingenieurleistungen ist Teil des Leistungswettbewerbs, der gemäß § 76 Abs. 1 VgV für Planungsleistungen zwingend vorgeschrieben ist. | Ein reiner Preiswettbewerb ist gemäß § 76 Abs. 1 VgV nicht zulässig und führt nicht zur gewünschten Qualität der Leistung. — printed p.34, p.39', verification_note='md-verified 2026-09-05 (§8.7 p.34, §8.10.3.1 p.39) [VC]', verified_at=now() where id='b0060a41-bf6a-45bf-b5fc-cd934d4599a1' and verification_status not in ('verified_against_standard','corrected');

-- mindesteignung_definiert
update public.fields set verification_status='verified_against_standard', verification_quote='Die Auswahl der Eignungskriterien einschließlich etwaiger Mindesteignungsanforderungen (bspw. Mindestumsätze) und deren Gewichtung müssen an dieser Stelle erläutert und begründet werden. Eine Blanko-Eignungsmatrix muss als Anlage zur Dokumentation hinzugelegt werden. | Eignungsanforderungen sind eindeutig zu formulieren. Der Wettbewerb darf dabei nicht unzulässig eingeengt werden. — printed p.66, p.38', verification_note='md-verified 2026-09-05 (Anh. F 3 p.66, §8.10.2.2 p.38) [VC]', verified_at=now() where id='5b53b7f3-93df-49cf-a569-44b0ef596d08' and verification_status not in ('verified_against_standard','corrected');

-- ---------- M820-12 Ausschlusskriterien ----------

-- exclusion_123_gwb_checked
update public.fields set verification_status='verified_against_standard', verification_quote='In § 123 GWB sind die zwingenden Ausschlussgründe aufgeführt. Im Rahmen der Vergabe wird je nach vorliegendem Tatbestand eine Eigen- oder Fremderklärung angefordert. Bereits das Nichtvorlegen der geforderten Erklärungen [...] führt zum Ausschluss. | Grundsätzlich nicht geeignet für die Ausführung eines Auftrags ist in einem VgV-F Verfahren ein Ingenieurbüro, bei dem zwingende Ausschlussgründe gemäß § 123 GWB vorliegen. [...] so ist es zwingend auszuschließen, soweit keine Selbstreinigung erfolgte. — printed p.58, p.35', verification_note='md-verified 2026-09-05 (Anh. E.1.1 p.58, §8.7 p.35) [VC]', verified_at=now() where id='90216f18-de86-4e61-bd91-0d2e9f6b53ec' and verification_status not in ('verified_against_standard','corrected');

-- exclusion_124_gwb_selected
update public.fields set verification_status='verified_against_standard', verification_quote='Dem Auftraggeber wird empfohlen, in den Vergabeunterlagen deutlich zu machen, ob er sich auf alle Ausschlussgründe gemäß § 124 GWB bezieht. Der Auftraggeber muss dann die Bewerber auffordern, entsprechend nachzuweisen (zuerst möglichst per Eigenerklärungen [...]), dass diese Ausschlussgründe nicht vorliegen. | Zusätzlich kann der Auftraggeber für das VgV-F-Verfahren Ausschlussgründe gemäß § 124 GWB angeben. Es wird dringend empfohlen, die ausgewählten Kriterien aus Gründen der Transparenz vorab bekannt zu machen. — printed p.58, p.35', verification_note='md-verified 2026-09-05 (Anh. E.1.2 p.58, §8.7 p.35; the individual §124 grounds are not printed in the Merkblatt (NR — external statute)) [VC]', verified_at=now() where id='61741ec0-a1c9-4484-982d-2a1ed7c55ebd' and verification_status not in ('verified_against_standard','corrected');

-- ---------- M820-13 Eignungskriterien ----------

-- min_annual_revenue_multiplier
update public.fields set verification_status='verified_against_standard', verification_quote='Als Mindestjahresumsatz nach § 45 Abs. 2 VgV darf der Auftraggeber nicht mehr als das Zweifache des geschätzten Auftragswerts verlangen. Dieser Wert ist insbesondere bei länger laufenden Projekten in der Regel zu hoch, er sollte sich auf den jährlich zu erwirtschaftenden Auftragswert und nicht auf den Gesamtauftragswert der Ingenieurleistungen beziehen. Bei großen, langlaufenden Projekten sollte das geforderte Verhältnis Jahresumsatz zu Jahresauftragswert den Faktor 1,5 nicht überschreiten. | Der Auftraggeber kann einen Mindestjahresumsatz vorgeben. Dieser darf in der Regel das Zweifache des geschätzten Auftragswerts - nicht zu verwechseln mit dem geschätzten Gesamtwert, denn dieser kann erheblich höher liegen - betragen. — printed p.61, p.35', verification_note='md-verified 2026-09-05 (Anh. E.1.4.1 p.61 (cap 2,0; "sollte … 1,5 nicht überschreiten" for large long projects), §8.7 p.35 ("kann … vorgeben" → is_required review STAGED S-4; §8.7 also says "mindestens den dreifachen Jahresumsatz zu fordern" — internal source tension, see Findings)) [VC]', verified_at=now() where id='0529c495-3ea1-457a-a6eb-ed1735a93e5f' and verification_status not in ('verified_against_standard','corrected');

-- references_required_count
update public.fields set verification_status='verified_against_standard', verification_quote='Nicht die Anzahl, sondern der Inhalt und die Güte der Referenzen ist von Bedeutung; schon eine einzige gute Referenz sollte, je nach Aufgabenstellung, die volle Punktzahl erbringen können. Es gilt: Klasse statt Masse. — printed p.60', verification_note='md-verified 2026-09-05 (Anh. E.1.3.6 p.60) [VC]', verified_at=now() where id='c4dbb4c8-5207-49a8-bc23-8bd6e7916cca' and verification_status not in ('verified_against_standard','corrected');

-- reference_period_years
update public.fields set verification_status='verified_against_standard', verification_quote='In § 46 VgV wird pauschal ein Referenzzeitraum von drei Jahren festgelegt. [...] Damit der Auftraggeber sich wirklich geeignete Referenzen nachweisen lassen kann, sollte er einen Referenzzeitraum projektspezifisch von mindestens 5 Jahren, besser 10 Jahren, zulassen. Dies ist in der Vergabeakte zu begründen, wobei vorstehende Gründe als Grundlage für die eigene Begründung dienen können. — printed p.60', verification_note='md-verified 2026-09-05 (Anh. E.1.3.6 p.60 (statutory default 3 a; DWA "sollte" ≥ 5 a, better 10 a — no gate encodes this recommendation, see Findings); references themselves are "zu empfehlen" (§8.7 p.35) → is_required review STAGED S-4) [VC]', verified_at=now() where id='05068b11-17d6-4f9a-9d59-387c46e8c5a6' and verification_status not in ('verified_against_standard','corrected');

-- min_personnel
update public.fields set verification_status='verified_against_standard', verification_quote='Bezüglich der Personalausstattung kann der Auftraggeber eine Mindestgröße fordern. Es darf jedoch nur eine Größe gefordert werden, die dem Auftragswert entspricht. Beträgt beispielweise der Auftragswert umgerechnet auf jedes Jahr der Planung nur rd. 125.000 € pro Jahr, wäre eine Forderung von mindestens 15 Mitarbeitern völlig überzogen. Eine Forderung von mindestens 3 Mitarbeitern wäre in diesem Fall ausreichend und angemessen. — printed p.36', verification_note='md-verified 2026-09-05 (§8.7 p.36) [VC]', verified_at=now() where id='b9e86d31-c9f5-432d-8782-3a39301bf48c' and verification_status not in ('verified_against_standard','corrected');

-- liability_insurance_personenschaden
update public.fields set verification_status='verified_against_standard', verification_quote='Die Höhe der geforderten Versicherungssummen richtet sich nach der Auftragssumme. Anhaltspunkt für die Höhe der geforderten Versicherungssumme kann Tabelle D. 1 in Anhang D geben. | Tabelle D.1: Deckungssummen für eine Haftpflichtversicherung in Abhängigkeit zu den Herstellungskosten | Geschätzte Baukosten & Deckungssumme für Personenschäden & Deckungssumme für sonstige Schäden | bis 0,5 Mio. € & 1,5 Mio. € & 0,25 Mio. € | bis 1,5 Mio. € & 1,5 Mio. € & 0,5 Mio. € | bis 4,0 Mio. € & 1,5 Mio. € & 1,0 Mio. € | bis 10 Mio. € & 2,0 Mio. € & 2,0 Mio. € | bis 25 Mio. € & 3,0 Mio. € & 3,0 Mio. € | bis 50 Mio. € & 3,0 Mio. € & 5,0 Mio. € — printed p.62, p.56', verification_note='md-verified 2026-09-05 (Anh. E.1.4.2 p.62, Tab. D.1 p.56 (RBBau values, "Anhaltspunkt … kann" → guidance, engineer sets the figure; overlaps M820-22.haftpflicht_versicherungssumme, STAGED S-2)) [VC]', verified_at=now() where id='c6d9609f-4d2c-4f52-82ff-ac8784e71969' and verification_status not in ('verified_against_standard','corrected');

-- liability_insurance_sonstige
