-- social_criteria_included
update public.fields set verification_status='verified_against_standard', verification_quote='Unter Bezug auf diese Grundlage können Kriterien, wie die Ausbildungsquote, Beschäftigung von Praktikanten, die Unterstützung der Forschung und der Lehre an Hochschulen sowie die Betreuung von Abschlussarbeiten, festgelegt werden. — printed p.62', verification_note='md-verified 2026-09-05 (Anh. E.1.5 p.62) [VC]', verified_at=now() where id='f5b592af-1268-4011-960d-fb3a9e9fef4d' and verification_status not in ('verified_against_standard','corrected');

