-- ---------- M820-14 Zuschlagskriterien ----------

-- doppelbewertungsverbot_check
update public.fields set verification_status='verified_against_standard', verification_quote='Es gilt aber auch in diesem Fall das Doppelbewertungsverbot, das heißt, verwendete Eignungskriterien dürfen nicht als Zuschlagskriterium verwendet werden. | In beiden Kriterien darf der Auftraggeber es nicht ansetzen, da er damit gegen das Doppelbewertungsverbot verstößt. — printed p.39, p.35', verification_note='md-verified 2026-09-05 (§8.10.2.4 p.39, §8.7 p.35 (§58 Abs. 2 VgV context)) [VC]', verified_at=now() where id='cb573c76-852f-40b8-9c8d-a8a2c4167ecc' and verification_status not in ('verified_against_standard','corrected');

-- price_weight_percent
update public.fields set verification_status='verified_against_standard', verification_quote='Der Auftraggeber kann bei der Vergabe von Ingenieurleistungen auch den Preis werten, muss es jedoch nicht. Wird der Preis gewertet, sollte seine Wertung aber nicht ein so hohes Gewicht erlangen, dass der Preis allein ausschlaggebend für die Vergabeentscheidung wird, weil allein über den Preiswettbewerb keine qualitätsvollen Ingenieurleistungen zu erlangen sind. | Bewährt hat sich ein Bewertungsgewicht für den Preis in Höhe von max. 20 %. — printed p.64', verification_note='md-verified 2026-09-05 (Anh. E.2.8 p.64; price weighting is optional ("kann … muss es jedoch nicht") → is_required review STAGED S-4; "Bewährt hat sich … max. 20 %" is advisory → REQ-15 block→warn in STAGED S-6) [VC]', verified_at=now() where id='4e74b2e7-01a2-4fdc-8236-b4b071c16f8a' and verification_status not in ('verified_against_standard','corrected');

-- schluesselpersonal_count
update public.fields set verification_status='verified_against_standard', verification_quote='Der Bauherr muss benennen, welche Funktionen er als Schlüsselpersonal im Projekt sieht. Dies sollte auf die projektbestimmenden Kompetenzen beschränkt werden (in der Regel ca. zwei bis vier Personen). Eine Orientierungshilfe für die Bestimmung des Schlüsselpersonals sind die ausgeschriebenen Leistungsbilder. — printed p.63', verification_note='md-verified 2026-09-05 (Anh. E.2.2 p.63 ("in der Regel ca. zwei bis vier" = advisory range, no gate)) [VC]', verified_at=now() where id='a5428dc5-e8df-4e35-bed7-08a737158c02' and verification_status not in ('verified_against_standard','corrected');

-- festpreis_used
update public.fields set verification_status='verified_against_standard', verification_quote='Alternative Vorgehensweise: Der Auftraggeber darf nach § 58 Abs. 2 VgV einen Festpreis vorgeben. Die Festpreisvorgabe muss HOAI-konform sein. Der Preis ist in diesem Fall kein Zuschlagskriterium mehr. — printed p.64', verification_note='md-verified 2026-09-05 (Anh. E.2.8 p.64 (also §8.10.3.3 p.40)) [VC]', verified_at=now() where id='22c045ad-c82f-41ae-a3c5-d02368ad7c03' and verification_status not in ('verified_against_standard','corrected');

-- award_criteria_list
update public.fields set verification_status='verified_against_standard', verification_quote='Um die Qualität der Ingenieurleistungen zu gewährleisten, sind aus Sicht der DWA-Arbeitsgruppe WI-4.4 mindestens die nachfolgenden Zuschlagskriterien notwendig. | Der Auftraggeber ist verpflichtet, spätestens bei der Aufforderung zur Angebotsabgabe, besser bereits bei der Bekanntmachung, die Zuschlagskriterien und deren Gewichtung anzugeben (§ 127 GWB). — printed p.63, p.40', verification_note='md-verified 2026-09-05 (Anh. E.2.1 p.63 (E.2.2–E.2.8 = the seven printed criteria in the description), §8.10.3.3 p.40) [VC]', verified_at=now() where id='94993fa3-63d9-4d56-9015-8e26e8953acc' and verification_status not in ('verified_against_standard','corrected');

-- ---------- M820-15 Dokumentationsstruktur ----------

-- documentation_structure
update public.fields set verification_status='verified_against_standard', verification_quote='Gemäß § 41 Abs. 1 VgV hat der Auftraggeber bereits mit Bekanntmachung, die Vergabeunterlagen unentgeltlich, uneingeschränkt, vollständig und direkt zur Verfügung zu stellen. § 29 Abs. 1 VgV definiert, aus welchen Bestandteilen sich die Vergabeunterlagen in der Regel zusammensetzen. — printed p.32', verification_note='md-verified 2026-09-05 (§8.2 p.32 (md prints "Abs .1")) [VC]', verified_at=now() where id='439d0bdc-0d84-4a2e-abf0-a1c6105df3d3' and verification_status not in ('verified_against_standard','corrected');

-- bewerbungsbedingungen_complete
update public.fields set verification_status='verified_against_standard', verification_quote='Die im Teilnahmewettbewerb gestellten Anforderungen erfährt das Ingenieurbüro entweder aus der europaweiten Bekanntmachung oder aus den Teilnahmeunterlagen, die es vom Auftraggeber abfordern kann. | In der Bekanntmachung muss neben den Eignungsanforderungen außerdem angegeben werden, ob an die Leistungserbringung besondere Anforderungen gestellt werden. — printed p.38, p.32', verification_note='md-verified 2026-09-05 (§8.10.2.1 p.38, §8.2 p.32) [VC]', verified_at=now() where id='7f5b3224-8549-4219-96cf-9210223026a6' and verification_status not in ('verified_against_standard','corrected');

-- eignungskriterien_dokumentiert
update public.fields set verification_status='verified_against_standard', verification_quote='Eignungskriterien müssen nach § 122 GWB in der Veröffentlichung den zu übersendenden Bewerbungsunterlagen genannt werden; es wird empfohlen, auch deren Gewichtung zu veröffentlichen. | Einmal veröffentlichte Eignungs- oder Zuschlagskriterien dürfen im laufenden Vergabeverfahren nicht mehr geändert werden. — printed p.38', verification_note='md-verified 2026-09-05 (§8.10.2.3 p.38) [VC]', verified_at=now() where id='c19735a4-5200-4c6a-aba0-8fcaaf15d928' and verification_status not in ('verified_against_standard','corrected');

-- leistungsbeschreibung_complete
update public.fields set verification_status='verified_against_standard', verification_quote='Die Aufgabenbeschreibung ist gemäß § 121 Abs. 3 GWB, § 29 Abs. 1 Nr. 3 VgV den Vergabeunterlagen beizufügen. Bei einem zweistufigen Verfahren ist es zwingend erforderlich, dass bereits in der Bewer- bungsphase die Leistung, um die sich das Unternehmen bewerben kann, beschrieben wird. — printed p.32', verification_note='md-verified 2026-09-05 (§8.2 p.32 (md hyphenates "Bewer- bungsphase", reproduced verbatim); overlaps M820-04.aufgabenbeschreibung_eindeutig) [VC]', verified_at=now() where id='0022e8b4-d5ff-4fc5-9c71-081c491ab186' and verification_status not in ('verified_against_standard','corrected');

