update public.fields set verification_status='verified_against_standard', verification_quote='Will der Auftraggeber die Ingenieurleistungen nach Qualitätskriterien vergeben, so muss er eine Bewertungskommission einsetzen, weil über diese der Sachverstand zur Beurteilung der angebotenen Qualität geschaffen werden kann. | 2. Bewertungskommission | Hier müssen die Namen und die zugehörigen Positionen/Funktionen der Bewertungskommission aufgelistet werden. — printed p.32, p.66', verification_note='md-verified 2026-09-05 (§8.4 p.32, Anh. F 2 p.66) [VC]', verified_at=now() where id='9fe6fef3-4ec5-412d-9669-cccf44974125' and verification_status not in ('verified_against_standard','corrected');

