update public.fields set verification_status='verified_against_standard', verification_quote='Will der Auftraggeber die Ingenieurleistungen nach Qualitätskriterien vergeben, so muss er eine Bewertungskommission einsetzen, weil über diese der Sachverstand zur Beurteilung der angebotenen Qualität geschaffen werden kann. | Die Bewertungskommission sollte bereits bei der Vorbereitung des Vergabeverfahrens und bei der Festlegung von Eignungs- und Zuschlagskriterien und deren Gewichtung eingebunden werden. — printed p.32, p.33', verification_note='md-verified 2026-09-05 (§8.4 p.32–33 (md hyphenates "Eig-nungs-"); clause_reference "§4" is wrong — §4 is "Grundsätze" (STAGED S-3 retag to §8.4)) [VC]', verified_at=now() where id='2798029b-c8e8-4b4d-b9a1-826f4c0c680c' and verification_status not in ('verified_against_standard','corrected');

-- bewertungskommission_size
update public.fields set verification_status='verified_against_standard', verification_quote='Insbesondere bei VgV-F-Verfahren hat der öffentliche Auftraggeber gemäß § 58 Abs. 5 VgV mindestens zwei Personen für die Wertung einzusetzen. [...] Die Bewertungskommission sollte überwiegend fachkundig mit einer ungeraden Mitgliederzahl besetzt sein. Alle Mitglieder haben gleiches Stimmrecht. — printed p.32', verification_note='md-verified 2026-09-05 (§8.4 p.32–33 (md prints "Abs .5"); hard floor 2 (REQ-09), "sollte … ungerade" is advisory, no gate; clause "§4" wrong (STAGED S-3)) [VC]', verified_at=now() where id='500d24b2-d2f5-4248-8d03-9a69a23898da' and verification_status not in ('verified_against_standard','corrected');

