update public.fields set verification_status='verified_against_standard', verification_quote='Die beabsichtigte Auftragsvergabe muss beim Amt für Veröffentlichungen der Europäischen Union mit dem vorgegebenen Bekanntmachungsmuster (siehe http://simap.europa.eu) europaweit bekannt gemacht werden, § 37 VgV. | Die Unterlagen zur Veröffentlichung müssen Anlage der Dokumentation werden. — printed p.38, p.66', verification_note='md-verified 2026-09-05 (§8.10.2.3 p.38, Anh. F 5 p.66; caveat: the source mandates the EU notice, the identifier string is the app''s handle for it) [VC]', verified_at=now() where id='d999e0bb-4397-4ff7-a3d1-6d49a38c4f00' and verification_status not in ('verified_against_standard','corrected');

