update public.fields set verification_status='verified_against_standard', verification_quote='Hier muss eine Zusammenfassung der Wertung der Bewerber (üblicherweise in Tabellenform) dargestellt werden. Diese sollte mindestens Folgendes enthalten: | die Namen der Bewerber, | die Erklärung, ob die Bewerbungen formal in Ordnung sind, | die erreichte Punktzahl, | die Rangfolge der Bewerber nach Wertung | und | die Erklärung, wer zur Angebotsphase zugelassen wird. — printed p.66', verification_note='md-verified 2026-09-05 (Anh. F 6 p.66; caveat: the source asks for the named list, the count is its aggregate) [VC]', verified_at=now() where id='60be0626-82f3-42d5-a57e-c69d1160b2f4' and verification_status not in ('verified_against_standard','corrected');

-- shortlisted_count
