update public.fields set verification_status='verified_against_standard', verification_quote='Nach Abgabe endgültiger Angebote ist anhand der Zuschlagskriterien dem Bieter der Auftrag zu erteilen, der die Zuschlagskriterien am besten erfüllt. | Hier muss eine Zusammenfassung der Wertung der Bieter (üblicherweise in Tabellenform) dargestellt werden. Diese sollte mindestens Folgendes enthalten: | die Namen der Bieter, | die erreichte Punktzahl, | und die Rangfolge der Bieter gemäß der Wertung. — printed p.39, p.66', verification_note='md-verified 2026-09-05 (§8.10.3.1 p.39, Anh. F 8 p.66; count = aggregate of the named list) [VC]', verified_at=now() where id='baa745d7-3176-4dd4-b02b-08c8fec7d9a1' and verification_status not in ('verified_against_standard','corrected');

-- bewertungs_kriterien_dokumentiert
