-- preisbewertung_durchgefuehrt
update public.fields set verification_status='verified_against_standard', verification_quote='Die Bewertung von Preisdifferenzen muss nach vorab definierten und bekannt gegebenen Formeln erfolgen. Diese Formel darf nicht dazu führen, dass lediglich geringfügige Preisdifferenzen zu erheblich abweichenden Bepunktungen führen. — printed p.64', verification_note='md-verified 2026-09-05 (Anh. E.2.8 p.64; price evaluation only exists if price is a criterion ("kann … muss es jedoch nicht") → is_required review STAGED S-4) [VC]', verified_at=now() where id='b831d563-472e-4293-9d8f-69472ea07fb6' and verification_status not in ('verified_against_standard','corrected');

-- qualitaetsbewertung_durchgefuehrt
