update public.fields set verification_status='verified_against_standard', verification_quote='Die Verhandlungsrunde schließt sich an die Abgabe des Erstangebots an. Weitere Verhandlungsrunden können folgen. | Bei schwierigen Planungen können mehrere Verhandlungsrunden und die Erstellung von immer wieder neuen vorläufigen Angeboten erforderlich sein, bevor das endgültige Angebot erstellt werden kann. — printed p.40, p.41', verification_note='md-verified 2026-09-05 (§8.10.3.4 p.40–41 (§17 Abs. 14 VgV in §8.10.3.1 p.39); VgV-F construct — REQ-20 fires unconditionally, see STAGED S-5) [VC]', verified_at=now() where id='91541f1d-3e54-4868-a745-96a1b1b88ea4' and verification_status not in ('verified_against_standard','corrected');

-- verhandlung_thema
update public.fields set verification_status='verified_against_standard', verification_quote='Eine Tagesordnung, aus der sich der Ablauf der Verhandlungsrunde ergibt, ist vom Auftraggeber zu erstellen. [...] In der Verhandlung muss ausreichend Zeit vorgesehen sein, damit sich der Bieter präsentieren kann, die Aufgabenbeschreibung und das Erstangebot besprochen werden können und der Auftraggeber Fragen stellen kann. — printed p.40', verification_note='md-verified 2026-09-05 (§8.10.3.4 p.40; VgV-F only — is_required review STAGED S-4) [VC]', verified_at=now() where id='d3a72553-ca9d-48d1-b009-3f69ed58cdae' and verification_status not in ('verified_against_standard','corrected');

