update public.fields set verification_status='verified_against_standard', verification_quote='Das Verhandlungsgespräch jeden Bieters muss zusammengefasst und dargestellt werden sowie die Gründe für die einzelne Bepunktung erläutert werden. | Ein mögliches Ergebnis ist, dass der Auftraggeber auf der Grundlage der Gesprächsergebnisse die Aufgabenbeschreibung und den Vertrag überarbeitet, allerdings ohne dass sich der Charakter des Auftrags ändert. — printed p.67, p.41', verification_note='md-verified 2026-09-05 (Anh. F 8 p.67, §8.10.3.4 p.41; VgV-F only — is_required review STAGED S-4) [VC]', verified_at=now() where id='badb10e4-bd98-4e32-8b9b-a845de268dd0' and verification_status not in ('verified_against_standard','corrected');

-- ---------- M820-21 Vertragscheckliste ----------

-- vertragsentwurf_in_unterlagen
update public.fields set verification_status='verified_against_standard', verification_quote='Ein Vertragsentwurf muss bereits Teil der Vergabeunterlagen und der Verhandlung sein, denn die Verhandlungen dienen dazu, dass der Auftraggeber am Ende einen Auftrag erteilen kann. Folglich muss der Vertragsentwurf bereits mit der Bekanntmachung vorliegen, kann sodann verhandelt werden und ist vor der Wertung der endgültigen Angebote abschließend zu klären. — printed p.41', verification_note='md-verified 2026-09-05 (§8.10.3.5 p.41 (§29 Abs. 1 VgV context in §8.2 p.32: "dringend empfohlen … Entwurf eines Vertrags bereits vor der Bekanntmachung fertigzustellen")) [VC]', verified_at=now() where id='a9689437-3b73-4e95-b7d3-4a7d974888ea' and verification_status not in ('verified_against_standard','corrected');

-- leistung_klar_definiert
update public.fields set verification_status='verified_against_standard', verification_quote='Der Vertragsentwurf muss sämtliche Elemente umfassen, die eine Auftragserteilung ermöglichen. Das sind insbesondere | die zu erfüllende Aufgabe (Leistung), | zu beachtende Besonderheiten, | Termine, | die Vergütung, | Vertragsbedingungen. | Wichtig ist die Beschreibung der Leistung und der Honorarparameter sowie der besonderen Leistungen, die für jeden Vertrag individuell erfolgen müssen. — printed p.41, p.55', verification_note='md-verified 2026-09-05 (§8.10.3.5 p.41, Anh. D p.55) [VC]', verified_at=now() where id='d8b747bc-5ab4-4218-95cc-fc5f68eef184' and verification_status not in ('verified_against_standard','corrected');

