update public.fields set verification_status='verified_against_standard', verification_quote='Außerdem muss der Vertrag die Parameter für die Honorierung und die Vergütung der besonderen Leistungen enthalten. Die Preise selbst sind von den Ingenieurbüros einzusetzen. — printed p.55', verification_note='md-verified 2026-09-05 (Anh. D p.55 (also §8.10.3.5 p.41 "die Vergütung")) [VC]', verified_at=now() where id='936c482d-b6c8-4848-b937-c7f5563c4085' and verification_status not in ('verified_against_standard','corrected');

-- gewaehrleistung_geregelt
update public.fields set verification_status='verified_against_standard', verification_quote='Die Mängelansprüche verjähren nach § 634a BGB, für die Herstellung eines Bauwerks und einem Werk, dessen Erfolg in der Erbringung von Planungs- oder Überwachungsleistungen hierfür besteht, nach 5 Jahren. | Ein unnötig langes Herauszögern des Gewährleistungsbeginns kann zu Problemen mit Ansprüchen gegenüber den Haftpflichtversicherungen der Ingenieurbüros führen. — printed p.54', verification_note='md-verified 2026-09-05 (Anh. C p.54) [VC]', verified_at=now() where id='8738cef8-5d2f-4aff-b5a1-6c20a069cec1' and verification_status not in ('verified_against_standard','corrected');

