-- haftpflicht_versicherungssumme
update public.fields set verification_status='verified_against_standard', verification_quote='Das Unternehmen muss die Existenz einer Berufshaftpflichtversicherung nachweisen oder die Bescheinigung einer Versicherung vorlegen, dass es im Auftragsfall über eine Berufshaftpflichtversicherung verfügen wird. Die Berufshaftpflichtversicherung muss die vom Auftraggeber gewünschten Deckungssummen aufweisen. | Als Deckungssummen für eine Haftpflichtversicherung empfiehlt das für das Bauwesen zuständige Bundesministerium in seinen Vertragsmustern im Wesentlichen folgende Beträge, in Abhängigkeit zu den Herstellungskosten (siehe Tabelle D.1). — printed p.62, p.55', verification_note='md-verified 2026-09-05 (Anh. E.1.4.2 p.62, Anh. D p.55–56; caveat: Tab. D.1 prints TWO sums (Personenschäden / sonstige Schäden) — this single figure overlaps the M820-13 pair (STAGED S-2)) [VC]', verified_at=now() where id='ec2f5db6-dbd6-4826-abbb-af33731203e5' and verification_status not in ('verified_against_standard','corrected');

