-- verschuldensgrenzen_definiert
update public.fields set verification_status='verified_against_standard', verification_quote='Allgemeine Vertragsbedingungen können auch als Anlage zum Vertrag hinzugefügt werden. In diesen sind Grundsätze der Zusammenarbeit, wie gegenseitige Pflichten, Vertretung, Auskunft, Kündigung, Haftung usw. zu regeln. | Falls aufgrund besonderer projektspezifischer Risiken oder anderer Gründe erhöhte Anforderungen an die Haftpflichtversicherung zu stellen sind, müssen diese in die Leistungsbeschreibung als besondere Leistung aufgenommen werden und sind von den Bietern gesondert zu bepreisen. — printed p.55, p.56', verification_note='md-verified 2026-09-05 (Anh. D p.55–56; caveat: the term "Verschuldensgrenzen" does not occur in the source — Anh. D only names "Haftung" as a topic to regulate; partial support, is_required review STAGED S-4) [VC]', verified_at=now() where id='b541bbff-467d-44aa-b0b5-8bfa7c058b2d' and verification_status not in ('verified_against_standard','corrected');

