update public.fields set verification_status='verified_against_standard', verification_quote='Vor Auftragserteilung hat der Auftraggeber die Bewerber und Bieter, die keinen Auftrag erhalten sollen, über die Gründe ihrer Nichtberücksichtigung zu informieren. Formelhafte Begründungen, wie zum Beispiel andere Angebote seinen wirtschaftlicher gewesen, sind dabei nicht ausreichend. Ferner ist mitzuteilen, wann frühestens der Auftrag erteilt werden wird. — printed p.42', verification_note='md-verified 2026-09-05 (§8.10.3.6 p.42 (§134 GWB); GWB applies oberschwellig only (§106 GWB, p.49) — REQ-22/REQ-26 fire unconditionally, see STAGED S-5) [VC]', verified_at=now() where id='fd8b53a6-8330-4c67-a187-fdd56a014063' and verification_status not in ('verified_against_standard','corrected');

