-- vergabevermerk_complete
update public.fields set verification_status='verified_against_standard', verification_quote='Der Auftraggeber hat bei einem VgV-F-Verfahren die internen, vergaberelevanten Dokumente chronologisch in einer Vergabeakte zu bündeln, externe Unterlagen sollten in gesonderten Akten gegebenenfalls mit Verweis auf die Vergabeakte geführt werden. Als Abschluss des Vergabeverfahrens ist ein Vergabevermerk anzufertigen (§ 8 VgV). | Bei einer Direktvergabe oder einem Suchverfahren ist der Auftraggeber zwar nicht dazu verpflichtet, sollte es aber bereits aus haushaltsrechtlichen Gründen oder bei dem Erhalt von Fördermitteln zwecks Dokumentation tun. — printed p.32', verification_note='md-verified 2026-09-05 (§8.3 p.32, Anh. F p.65; mandatory for VgV-F, "sollte" for Direktvergabe/Suchverfahren — REQ-23 block is unconditional, see STAGED S-5) [VC]', verified_at=now() where id='f8d2ecd7-a92a-4fc4-ab60-d300978b7a34' and verification_status not in ('verified_against_standard','corrected');

